@props(['icon', 'size' => 20])

{{--
| Glifele oficiale ale rețelelor, ca SVG inline.
|
| Nu Font Awesome de pe CDN: site-ul vechi trăgea ~70 KB de JS blocant pentru
| vreo 25 de iconițe. Astea sunt câțiva octeți fiecare și moștenesc `currentColor`,
| deci se energizează auriu odată cu butonul care le conține.
|
| Toate au viewBox 24×24 și `fill="currentColor"` (nu stroke) — sunt logo-uri
| solide, nu pictograme de contur.
--}}
<svg
    {{ $attributes }}
    width="{{ $size }}"
    height="{{ $size }}"
    viewBox="0 0 24 24"
    fill="currentColor"
    aria-hidden="true"
    focusable="false"
>
